"""Admission gate: only architectures generated by the axiom system pass.

An architecture manifest (information_boltzmann/architectures/<name>.json) lists
every mechanism of the model. The gate admits the model only if all four layers pass:

1. Lineage. Every mechanism of kind "mechanism" or "structure" cites Lean theorems
   that exist in the current audit inventory and depend only on the standard axioms
   (propext, Classical.choice, Quot.sound). The inventory must match the current
   sources. Only kind "constant" (numbers that learning or evolution may tune) may
   cite nothing, and kind "selected" (table entries found by selection on survival, not
   designed) needs an existing selection record as evidence.
2. Execution. Every licensed mechanism names checks that run on the real
   implementation and confirm it computes what the theorem states.
3. Medium. The manifest names a Lean `Medium` instance whose `Axioms` proof is in
   the inventory.
4. Life (mandatory, 2026-10-26). Being a medium is not being alive. Every necessity the
   chain has proved for living organisms is an obligation, not an option:
   - Lean: the organism module proves `exposed` (`Lives.exposed`: it senses) and
     `metabolizes` (`Lives.metabolizes`: it exchanges content);
   - export (G16 `export_forced`): some boundary event lowers content;
   - selective export (G17 `retention_needs_selectivity`): export propensity differs
     between kinds of unit;
   - memory (`Lives.remembers`, G19 `memory_separates`), finite-horizon form: a one-tick
     boundary pulse is decodable from the state after it has been withdrawn for a tick;
   - self-maintenance (`Lives.selfMaintains`): closed-loop survival on held-out worlds
     exceeds the loop-cut (or blind) control in its selection record.

Usage: python scripts/cgb_gate.py <name> [--json out.json] [--require-admitted]
"""

from __future__ import annotations

import argparse
import copy
import hashlib
import json
from pathlib import Path
import sys

import numpy as np

ROOT = Path(__file__).resolve().parents[1]
ARCH = ROOT / "information_boltzmann" / "architectures"
LEAN = ROOT / "lean" / "CGBAxioms"
INVENTORY = LEAN / ".lake" / "audit_inventory.json"
STANDARD = {"propext", "Classical.choice", "Quot.sound"}
sys.path.insert(0, str(ROOT / "information_boltzmann" / "core"))


def load_inventory():
    data = json.loads(INVENTORY.read_text(encoding="utf-8"))
    sources = sorted((LEAN / "CGBAxioms").rglob("*.lean")) + [LEAN / "CGBAxioms.lean"]
    current = {p.relative_to(LEAN).as_posix(): hashlib.sha256(p.read_bytes()).hexdigest() for p in sources}
    fresh = current == data.get("source_hashes")
    trusted = bool(data.get("proof_trust_passed")) and bool(data.get("module_coverage_passed"))
    return {d["name"]: d for d in data["declarations"]}, fresh, trusted


# ---------- executable checks on the real implementation ----------

class _Forced:
    """Stands in for the organism's random source so act() takes a chosen action."""

    def __init__(self, action):
        self.u = 0.0 if action == 1 else 1.0

    def random(self):
        return self.u


def _organism(hidden=16, seed=3):
    from cgb_lg1_forager import G15Organism
    m = G15Organism(hidden, seed=seed, eta=0.05, relax=1.0, diffuse=0.3, feedback=0.1, recur=2.0,
                    pg_eta=0.1, pg_trace=0.9)
    rng = np.random.default_rng(seed)
    m.Wp = rng.normal(0, 0.7, m.Wp.shape)
    m.p1 = rng.random(hidden).astype(np.float32)
    m.ate, m.n, m.bl = 1, 3, 0.4
    return m


def _policy(m):
    z = m.Wp @ m.features()
    pi = np.exp(z - z.max())
    return pi / pi.sum()


def _forced_update(m, action, intake):
    m = copy.deepcopy(m)
    m.ep[:] = 0.0
    m.prng = _Forced(action)
    w0 = m.Wp.copy()
    assert m.act() == action
    m.learning = False
    m.sense(65, intake, False)
    return m.Wp - w0


def check_softmax_readout():
    m = _organism()
    pi = _policy(m)
    m.prng = np.random.default_rng(0)
    counts = np.zeros(2)
    for _ in range(20000):
        counts[m.act()] += 1
    freq = counts / counts.sum()
    return abs(freq[1] - pi[1]) < 0.02, dict(softmax_switch=float(pi[1]), empirical_switch=float(freq[1]))


def check_g15_policy_gradient():
    m = _organism()
    R = {0: 1, 1: 0}
    x, pi = m.features(), _policy(m)
    expected = sum(pi[a] * _forced_update(m, a, R[a]) for a in (0, 1))
    J = sum(pi[a] * R[a] for a in (0, 1))
    theorem = m.pg_eta * np.outer([pi[b] * (R[b] - J) for b in (0, 1)], x)
    err = float(np.abs(expected - theorem).max())
    return err < 1e-9, dict(max_abs_error=err, baseline=m.bl)


def check_g15_outcome_blind_zero():
    m = _organism()
    pi = _policy(m)
    drift = sum(pi[a] * _forced_update(m, a, 1) for a in (0, 1))
    err = float(np.abs(drift).max())
    return err < 1e-9, dict(max_abs_drift=err)


def check_g14_delta_rule():
    from cgb_lg1 import LG1
    m = LG1(16, seed=5, eta=0.05, relax=1.0, diffuse=0.3, feedback=0.1)
    rng = np.random.default_rng(5)
    m.W1 = rng.normal(0, 0.3, m.W1.shape).astype(np.float32)
    m.p1 = rng.random(16).astype(np.float32)
    pi, p, w0, b = m.predict(), m.p1.copy(), m.W1.copy(), 101
    m.observe(b)
    e = -pi
    e[b] += 1.0
    err = float(np.abs((m.W1 - w0) - m.eta * np.outer(p - 0.5, e)).max())
    return err < 1e-5, dict(max_abs_error=err)


def check_miss_counter_distinguishes():
    m = _organism()
    m.ate, m.n = 0, 0
    seen = set()
    for _ in range(m.nmax + 1):
        seen.add(int(np.argmax(m.features()[:m.ns])))
        m.sense(65, 0, False)
    return len(seen) == m.nmax + 1, dict(distinct_states=len(seen), required=m.nmax + 1)


def check_interior_symmetric():
    m = _organism()
    err = float(np.abs(m.R - m.R.T).max())
    return err == 0.0, dict(max_asymmetry=err)


def check_score_trace_geometric():
    m = _organism()
    rng = np.random.default_rng(1)
    m.ep = rng.normal(0, 1, m.Wp.shape)
    before = m.ep.copy()
    m.prng = _Forced(1)
    x, pi = m.features(), _policy(m)
    m.act()
    score = -pi
    score[1] += 1.0
    err = float(np.abs(m.ep - (m.pg_lam * before + np.outer(score, x))).max())
    return err < 1e-12, dict(max_abs_error=err, decay=m.pg_lam)


def check_p2_symmetric_exchange():
    from cgb_lg1 import LG1
    m = LG1(16, seed=7, eta=0.05, relax=0.0, diffuse=0.3, feedback=0.1)
    rng = np.random.default_rng(7)
    m.p1 = rng.random(16).astype(np.float32)
    m.p2 = rng.random(16).astype(np.float32)
    p1, p2 = m.p1.astype(np.float64), m.p2.astype(np.float64)
    m.observe(66)
    tot = float(np.abs((m.p1 + m.p2) - (p1 + p2)).max())
    diff = float(np.abs((m.p1 - m.p2) - (1 - 2 * m.diffuse) * (p1 - p2)).max())
    return max(tot, diff) < 1e-5, dict(total_error=tot, difference_error=diff)


def check_grown_R_rule():
    from cgb_lg1_forager import G15Organism
    m = G15Organism(16, seed=4, eta=0.05, relax=1.0, diffuse=0.3, feedback=0.1, grown_R=True)
    rng = np.random.default_rng(4)
    for _ in range(50):
        m.prng = rng
        m.act()
        m.sense(int(rng.integers(32, 127)), int(rng.random() < 0.5), False)
    g = m.growth
    sym = float(np.abs(m.R - m.R.T).max())
    recip = float(np.abs(m.R - g.kappa / g.n_c * g.n).max())
    # the occupancy target is the G18c sigmoid of kappa * c - theta_i - theta_j
    field = g.kappa * g.c - (g.theta[:, None] + g.theta[None, :])
    occ = 1.0 / (1.0 + np.exp(-np.clip(field, -60, 60)))
    form = float(np.abs(g.target() - occ).max())
    ok = sym < 1e-6 and recip < 1e-5 and form < 1e-12 and float(np.abs(g.c - g.c.T).max()) < 1e-12
    return ok, dict(asymmetry=sym, reciprocity_error=recip, occupancy_form_error=form)


def _table(name):
    from cgb_table_medium import load
    return load(ROOT / "information_boltzmann" / "organisms" / f"{name}.json")


def check_table_lean_hash(name):
    t = _table(name)
    module = "".join(w.capitalize() for w in name.replace("_", " ").split()) if name != "ecoli_v1" else "EcoliV1"
    if name.startswith("generated_"):
        module = "Generated" + name.split("_", 1)[1].capitalize()
    lean = (LEAN / "CGBAxioms" / f"GenerationOrganism{module}.lean").read_text(encoding="utf-8")
    ok = t["sha256"] in lean
    return ok, dict(table_sha256=t["sha256"], lean_module=f"GenerationOrganism{module}")


def check_table_rates_match_lean(name):
    """The compiled simulator's rate of every rule direction equals the sum, over units, of
    the unit-level rates transcribed from the Lean definitions."""
    from cgb_table_medium import unit_pages, unit_rates
    from cgb_table_fast import _rates, arrays, table_genome
    t = _table(name)
    g = table_genome(t)
    counts, phi, bnd, ri, rj, a0, a1, b0, b1, kap = arrays(g)
    pages = unit_pages(t)
    P = len(t["pages"])
    rng = np.random.default_rng(11)
    worst = 0.0
    for _ in range(200):
        x = [int(rng.integers(2)) for _ in pages]
        mu_page = {p: float(rng.choice([-6.0, 0.0, 6.0])) if p in t["boundary_pages"] else 0.0 for p in range(P)}
        n = np.zeros((P, 2), dtype=np.int64)
        for u, p in enumerate(pages):
            n[p, x[u]] += 1
        w = np.zeros(2 * len(t["rules"]))
        _rates(n, phi, bnd, np.array([mu_page[p] for p in range(P)]), ri, rj, a0, a1, b0, b1, kap, w)
        ref = np.zeros_like(w)
        for (k, d, _u, _v), r in unit_rates(t, x, mu_page).items():
            ref[2 * k + int(d)] += r
        worst = max(worst, float(np.abs(w - ref).max() / max(1.0, float(np.abs(ref).max()))))
    return worst < 1e-9, dict(max_relative_error=worst, states=200)


def check_table3_rates_match_lean(name):
    """Multi-state tables (`cgb_table3`, the simulator of the generated organisms): the compiled
    rate of every rule direction equals the sum of the unit-level rates transcribed from the
    Lean definitions. Unit-level enumeration is quadratic in units, so the check runs on a copy
    with at most 5 units per page (rates depend on the table only through counts)."""
    from cgb_table_medium import unit_pages, unit_rates
    from cgb_table3 import _rates
    t = dict(_table(name))
    t["units"] = {k: min(v, 5) for k, v in t["units"].items()}
    counts, phi, bnd, R, kap, S = _table_arrays(t)
    nst = {int(p): int(v) for p, v in t.get("states", {}).items()}
    pages = unit_pages(t)
    P = len(t["pages"])
    rng = np.random.default_rng(11)
    worst = 0.0
    for _ in range(200):
        x = [int(rng.integers(nst.get(p, 2))) for p in pages]
        mu_page = {p: float(rng.choice([-6.0, 0.0, 2.0, 6.0])) if p in t["boundary_pages"] else 0.0 for p in range(P)}
        n = np.zeros((P, S), dtype=np.int64)
        for u, p in enumerate(pages):
            n[p, x[u]] += 1
        w = np.zeros(2 * len(t["rules"]))
        _rates(n, phi, bnd, np.array([mu_page[p] for p in range(P)]), R, kap, w)
        ref = np.zeros_like(w)
        for (k, d, _u, _v), r in unit_rates(t, x, mu_page).items():
            ref[2 * k + int(d)] += r
        worst = max(worst, float(np.abs(w - ref).max() / max(1.0, float(np.abs(ref).max()))))
    return worst < 1e-9, dict(max_relative_error=worst, states=200, units_per_page_cap=5)


def check_table_is_record(name):
    """The admitted table is the one selection produced: every field except name/status equals
    the `table` of the selection record named in the architecture manifest's life section."""
    t = _table(name)
    man = json.loads((ARCH / f"{name}.json").read_text(encoding="utf-8"))
    rec = json.loads((ROOT / man["life"]["record"]).read_text(encoding="utf-8"))["table"]
    keys = [k for k in rec if k not in ("name", "status")]
    diff = [k for k in keys if rec[k] != t.get(k)]
    return not diff, dict(record=man["life"]["record"], differing_fields=diff)


def check_nested_world_rates_match_lean(name):
    """Worlds (`cgb_nested_world`): on a 6 x 6 copy of the torus, the rate of every effective event
    of the exact kernel and of the batched torch world equals the sum of the Lean medium's event
    rates with that effect, transcribed here independently from `NestedWorld.eff1/eff2/c1/c2`,
    `LatticeCRN.medium.rate` (`c * exp(-dE / 2)`, `dE` with reservoir work at boundary cells,
    pages `torusPage`, boundary `bidW = [9, 26]`, neighbours `torusAdj`, energy `cellF`)."""
    import math as m
    import cgb_nested_world as NW
    tbl = copy.deepcopy(NW.load(name))
    G = tbl["geometry"]["G"] = 6
    t = tbl["table"]
    V, P, kin, kdiff = t["V"], t["pellet"], t["kappa_in"], t["kappa_diff"]
    kind = NW.kinds(G)
    page = {(x, y): 9 * int(kind[x, y]) + 3 * (x % 3) + y % 3 for x in range(G) for y in range(G)}
    cells = list(page)

    def adj(u, v):
        return u != v and ((u[0] == v[0] and ((u[1] + 1) % G == v[1] or (v[1] + 1) % G == u[1])) or
                           (u[1] == v[1] and ((u[0] + 1) % G == v[0] or (v[0] + 1) % G == u[0])))

    def cellF(k):
        return -(m.lgamma(V + 1) - m.lgamma(k + 1) - m.lgamma(V - k + 1))

    def shift(k, d):
        return k + d if 0 <= k + d <= V else None

    def phi(l):
        return cellF(l[0]) + cellF(l[1])

    def content(l):
        return l[0] + l[1]

    def eff1(food, dr, i, l):
        if food:
            d = -P if dr else P
            if i // 9 == 1 and shift(l[0], d) is not None:
                return (l[0] + d, l[1])
            return l
        d = -1 if dr else 1
        if i // 9 == 2 and shift(l[1], d) is not None:
            return (l[0], l[1] + d)
        return l

    def eff2(food, dr, l, l2):
        d = 1 if dr else -1
        k = 0 if food else 1
        a, b = shift(l[k], d), shift(l2[k], -d)
        if a is None or b is None:
            return l, l2
        l, l2 = list(l), list(l2)
        l[k], l2[k] = a, b
        return tuple(l), tuple(l2)

    rng = np.random.default_rng(5)
    worst = 0.0
    import torch
    th_world = NW.World(tbl, B=1, device="cpu", dtype=torch.float64)
    for trial in range(30):
        f = rng.choice([0, 1, 2, V // 2, V - 1, V], size=(G, G)) if trial % 3 == 0 else rng.integers(0, V + 1, size=(G, G))
        w = rng.integers(0, V + 1, size=(G, G)) if trial % 2 else rng.integers(0, 4, size=(G, G))
        mu = rng.choice([-8.0, 0.0, 8.0], size=(G, G)) + (rng.normal(size=(G, G)) if trial % 2 else 0.0)
        x = {c: (int(f[c]), int(w[c])) for c in cells}
        res = {c: (float(mu[c]) if 9 <= page[c] <= 26 else 0.0) for c in cells}
        ref = {}
        for c in cells:   # single-cell rules: rate c1 * exp(-dE1 / 2)
            for food in (True, False):
                for dr in (True, False):
                    l2 = eff1(food, dr, page[c], x[c])
                    if l2 == x[c]:
                        continue
                    dE = phi(l2) - phi(x[c]) - res[c] * (content(l2) - content(x[c]))
                    key = (c, "f" if food else "w", content(l2) - content(x[c]))
                    ref[key] = ref.get(key, 0.0) + kin * m.exp(-dE / 2)
        for u in cells:   # neighbour rules on ordered pairs: rate c2 * exp(-dE2 / 2)
            for v in cells:
                if not adj(u, v):
                    continue
                for food in (True, False):
                    for dr in (True, False):
                        a, b = eff2(food, dr, x[u], x[v])
                        if (a, b) == (x[u], x[v]):
                            continue
                        rs = res[u] if 9 <= page[u] <= 26 else res[v]
                        dE = (phi(a) + phi(b) - phi(x[u]) - phi(x[v]) -
                              rs * (content(a) + content(b) - content(x[u]) - content(x[v])))
                        k = 0 if food else 1
                        src, dst = (v, u) if a[k] > x[u][k] else (u, v)
                        key = (src, dst, "f" if food else "w")
                        ref[key] = ref.get(key, 0.0) + kdiff * m.exp(-dE / 2)
        out = NW.rates_np(f.astype(np.int64), w.astype(np.int64), mu.astype(np.float64), kind, tbl)
        th_world.f[0] = torch.tensor(f)
        th_world.w[0] = torch.tensor(w)
        tr = th_world.rates(torch.tensor(mu)[None]).numpy()[0]
        got_k, got_t = {}, {}
        for (xx, yy) in cells:
            c = xx * G + yy
            for e in range(12):
                if out[c, e] == 0.0 and tr[e, xx, yy] == 0.0:
                    continue
                if e < 4:
                    key = ((xx, yy), "f" if e < 2 else "w", (P if e == 0 else -P) if e < 2 else (1 if e == 2 else -1))
                else:
                    s, d = (e - 4) // 4, (e - 4) % 4
                    dx, dy = NW.World.SHIFT[d]
                    key = ((xx, yy), ((xx + dx) % G, (yy + dy) % G), "f" if s == 0 else "w")
                got_k[key] = got_k.get(key, 0.0) + out[c, e]
                got_t[key] = got_t.get(key, 0.0) + float(tr[e, xx, yy])
        for got in (got_k, got_t):
            keys = set(ref) | set(got)
            for kk in keys:
                a, b = ref.get(kk, 0.0), got.get(kk, 0.0)
                worst = max(worst, abs(a - b) / max(1e-12, abs(a), abs(b)))
    info = dict(max_relative_error=worst, states=30, G=G)
    ok = worst < 1e-9
    if torch.cuda.is_available():   # the fused float32 leap computes the same rates
        import cgb_nested_world_triton as NT
        tb = copy.deepcopy(NW.load(name))
        Gf = tb["geometry"]["G"]
        fw = NT.FusedWorld(tb, B=4)
        rw = NW.World(tb, B=4, device="cuda", dtype=torch.float64)
        fworst = 0.0
        for trial in range(5):
            f = torch.tensor(rng.integers(0, V + 1, size=(4, Gf, Gf)), device="cuda")
            f[0, :2] = 0
            f[1, :2] = V
            w = torch.tensor(rng.integers(0, 40, size=(4, Gf, Gf)), device="cuda")
            mu = torch.tensor(rng.choice([-8.0, 0.0, 8.0], size=(4, Gf, Gf)), device="cuda")
            fw.f.copy_(f)
            fw.w.copy_(w)
            rw.f.copy_(f)
            rw.w.copy_(w)
            a, r = fw.rates(mu).double(), rw.rates(mu)
            if not ((a == 0) == (r == 0)).all():
                fworst = float("inf")
            fworst = max(fworst, ((a - r).abs() / r.abs().clamp(min=1e-12)).max().item())
        info["fused_max_relative_error"] = fworst
        ok = ok and fworst < 1e-5
    return ok, info


def check_nested_organism_rates_match_lean(name):
    """Organisms nested in a world (`cgb_nested_organism`): for random genomes, inner states and
    pools, every rate column of the engine equals the sum of the Lean medium's event rates with
    that effect, transcribed here unit by unit from `NestedWorld.eff1/eff2/c1/c2` (inner pair rules
    on ordered unit pairs, exchanges with conductance `xκ * (gated ? intact membrane : 1)` and
    energy `dφ + cellF(pool') - cellF(pool)`, turns `(a, b)` while the motor is not running,
    forward and backward moves on ordered cell pairs with the fuel rule)."""
    import math as m
    import torch
    import cgb_nested_world as NW
    import cgb_nested_organism as NO
    tbl = NW.load(name)
    V = tbl["table"]["V"]
    rng = np.random.default_rng(9)
    B = 6

    class Stub:
        pass

    st = Stub()
    st.B, st.G, st.V, st.dt = B, 6, V, 0.05
    st.f = torch.zeros(B, 6, 6, dtype=torch.int32)
    st.w = torch.zeros(B, 6, 6, dtype=torch.int32)
    org = NO.Organisms(st, NO.random_genomes(B, rng), seed=1)
    pageIn = [p for p, u in enumerate(NO.UNITS) for _ in range(u)]
    phi = org.phi.double().numpy()
    kr, kx = org.kr.double().numpy(), org.kx.double().numpy()
    kflip, kmove = org.kflip.double().numpy(), org.kmove.double().numpy()

    def cellF(k):
        return -(m.lgamma(V + 1) - m.lgamma(k + 1) - m.lgamma(V - k + 1))

    worst = 0.0
    for trial in range(8):
        ys, fs, ws = [], [], []
        for b in range(B):
            y = [int(rng.integers(NO.STATES[p])) for p in pageIn]
            if trial % 4 == 0:
                for u, p in enumerate(pageIn):
                    if p == NO.S:
                        y[u] = 0           # dead: no intact membrane
            ys.append(y)
            fs.append(int(rng.choice([0, 1, 3, 50, V - 1, V])))
            ws.append(int(rng.choice([0, 1, 7, V - 1, V])))
        n = torch.zeros(B, 6, NO.SMAX, dtype=torch.int32)
        for b in range(B):
            for u, p in enumerate(pageIn):
                n[b, p, ys[b][u]] += 1
        org.n.copy_(n)
        got = org.rates(torch.tensor(fs, dtype=torch.int32), torch.tensor(ws, dtype=torch.int32)).double().numpy()
        for b in range(B):
            y = ys[b]
            ref = np.zeros(got.shape[1])
            bugE = lambda yy: sum(phi[b, pageIn[u], yy[u]] for u in range(len(yy)))
            c = 0
            for r, (i, j, a1, a2, b1, b2) in enumerate(NO.RULES):        # spec k, (u, v, dir)
                for dr in (0, 1):
                    src = (b1, b2) if dr else (a1, a2)
                    dst = (a1, a2) if dr else (b1, b2)
                    for u in range(len(y)):
                        for v in range(len(y)):
                            if u == v or pageIn[u] != i or pageIn[v] != j or (y[u], y[v]) != src:
                                continue
                            y2 = list(y)
                            y2[u], y2[v] = dst
                            ref[c + dr] += kr[b, r] * m.exp(-(bugE(y2) - bugE(y)) / 2)
                c += 2
            gate = sum(1 for u in range(len(y)) if pageIn[u] == NO.GATE[0] and y[u] == NO.GATE[1])
            for x, (p, a, bb, food, gated) in enumerate(NO.EXCH):        # exchange j, (u, dir)
                for dr in (0, 1):
                    s0, s1 = (bb, a) if dr else (a, bb)
                    d = s0 - s1
                    pool = fs[b] if food else ws[b]
                    for u in range(len(y)):
                        if pageIn[u] != p or y[u] != s0 or not 0 <= pool + d <= V:
                            continue
                        y2 = list(y)
                        y2[u] = s1
                        dE = bugE(y2) - bugE(y) + cellF(pool + d) - cellF(pool)
                        ref[c + dr] += kx[b, x] * (gate if gated else 1) * m.exp(-dE / 2)
                c += 2
            motor = [u for u in range(len(y)) if pageIn[u] == NO.M][0]
            if y[motor] != NO.RUN:                                       # turns (a, b), b != a
                ref[c] = 3 * kflip[b]
            c += 1
            i, j, a1, a2, b1, b2 = NO.FUEL                               # moves (e, d, dir)
            for fwd in (True, False):
                src = (a1, a2) if fwd else (b1, b2)
                dst = (b1, b2) if fwd else (a1, a2)
                for e in range(len(y)):
                    for dd in range(len(y)):
                        if e == dd or pageIn[e] != i or pageIn[dd] != j or (y[e], y[dd]) != src:
                            continue
                        y2 = list(y)
                        y2[e], y2[dd] = dst
                        if y[motor] == NO.RUN and y2[motor] == NO.RUN:
                            ref[c + (0 if fwd else 1)] += kmove[b] * m.exp(-(bugE(y2) - bugE(y)) / 2)
            for k in range(len(ref)):
                a_, g_ = ref[k], got[b, k]
                worst = max(worst, abs(a_ - g_) / max(1e-30, abs(a_), abs(g_)))
    return worst < 1e-5, dict(max_relative_error=worst, states=8 * B)


def check_nested_organism_kernel_matches(name):
    """The exact GPU organism kernel (`cgb_nested_organism_triton`, generated from the table):
    (1) its rate columns equal `Organisms.rates` (itself checked against Lean) on random genomes
    and states; (2) its events do what the columns say: from one fixed state, in a leap so short
    that almost no lane has two events, the lanes' state changes are classified by the effect
    pattern of each column, and each pattern's frequency matches its share of the total rate."""
    import torch
    if not torch.cuda.is_available():
        return False, dict(error="needs CUDA")
    import cgb_nested_world as NW
    import cgb_nested_organism as NO
    import cgb_nested_organism_triton as NX
    tbl = NW.load(name)
    V = tbl["table"]["V"]
    rng = np.random.default_rng(13)

    class Stub:
        pass

    def world(B, dt):
        st = Stub()
        st.B, st.G, st.V, st.dt = B, 3, V, dt
        st.f = torch.tensor(rng.choice([0, 1, 5, 60, V - 1, V], size=(B, 3, 3)), dtype=torch.int32, device="cuda")
        st.w = torch.tensor(rng.choice([0, 1, 4, V], size=(B, 3, 3)), dtype=torch.int32, device="cuda")
        return st

    def rand_n(B):
        n = torch.zeros(B, 6, NO.SMAX, dtype=torch.int32)
        for p, u in enumerate(NO.UNITS):
            for b in range(B):
                cuts = np.sort(rng.integers(0, u + 1, size=NO.STATES[p] - 1))
                parts = np.diff(np.concatenate([[0], cuts, [u]]))
                for s_, c in enumerate(parts):
                    n[b, p, s_] = int(c)
        return n.cuda()

    B = 256
    o = NX.ExactOrganisms(world(B, 0.05), NO.random_genomes(B, rng), seed=2)
    o.n32.copy_(rand_n(B))
    o.n = o.n32
    worst = 0.0
    a = o.kernel_rates().double()
    ref = NO.Organisms.rates(o).double()
    worst = ((a - ref).abs() / ref.abs().clamp(min=1e-30)).max().item()
    rate_ok = worst < 1e-5 and bool(((a == 0) == (ref == 0)).all())
    # effects
    L = 1 << 20
    g1 = NO.random_genomes(1, rng)
    g = {k: np.repeat(np.asarray(v)[None] if np.ndim(v) == 0 else np.asarray(v)[:1], L, axis=0) for k, v in g1.items()}
    st = world(1, 1.0)
    f0, w0 = int(st.f[0, 0, 0]), int(st.w[0, 0, 0])
    o1 = NX.ExactOrganisms(world(1, 1.0), g1, seed=3)
    o1.n32.copy_(rand_n(1))
    o1.n32[0, NO.M, :] = 0
    o1.n32[0, NO.M, int(rng.integers(2))] = 1
    o1.n = o1.n32
    o1.x32.zero_(); o1.y32.zero_(); o1.x.zero_(); o1.y.zero_()
    o1.W.f.fill_(f0); o1.W.w.fill_(w0)
    r1 = NO.Organisms.rates(o1)[0].double().cpu().numpy()
    tot = r1.sum()
    dt = 0.01 / tot
    ow = Stub()
    ow.B, ow.G, ow.V, ow.dt = L, 3, V, dt
    ow.f = torch.full((L, 3, 3), f0, dtype=torch.int32, device="cuda")
    ow.w = torch.full((L, 3, 3), w0, dtype=torch.int32, device="cuda")
    oL = NX.ExactOrganisms(ow, g, seed=4)
    oL.n32.copy_(o1.n32.expand(L, -1, -1))
    oL.n = oL.n32
    oL.x32.zero_(); oL.y32.zero_(); oL.h32.zero_()
    n0 = oL.n32.clone()
    oL.leap()
    dn = (oL.n32 - n0).view(L, -1).cpu().numpy()
    dfo = (ow.f[:, 0, 0] - f0).cpu().numpy()
    dwo = (ow.w[:, 0, 0] - w0).cpu().numpy()
    dh = oL.h32.cpu().numpy()
    pos = (oL.x32 * 3 + oL.y32).cpu().numpy()
    changed = (np.abs(dn).sum(1) > 0) | (dfo != 0) | (dwo != 0) | (dh != 0) | (pos != 0)
    pats = {}

    def add(c, ch, df=0, dw=0, kind="plain"):
        d = np.zeros(6 * NO.SMAX, dtype=np.int64)
        for (p_, s_, v_) in ch:
            d[p_ * NO.SMAX + s_] += v_
        pats.setdefault((tuple(d), df, dw, kind), []).append(c)

    c = 0
    for (i, j, a1, a2, b1, b2) in NO.RULES:          # effects read from the table itself
        add(c, [(i, a1, -1), (j, a2, -1), (i, b1, 1), (j, b2, 1)])
        add(c + 1, [(i, b1, -1), (j, b2, -1), (i, a1, 1), (j, a2, 1)])
        c += 2
    for (p_, a_, b_, food, gated) in NO.EXCH:
        for (s0, s1) in ((a_, b_), (b_, a_)):
            dd = s0 - s1
            add(c, [(p_, s0, -1), (p_, s1, 1)], df=dd if food else 0, dw=0 if food else dd)
            c += 1
    add(c, [], kind="turn")
    i, j, a1, a2, b1, b2 = NO.FUEL
    add(c + 1, [(i, a1, -1), (j, a2, -1), (i, b1, 1), (j, b2, 1)], kind="fwd")
    add(c + 2, [(i, b1, -1), (j, b2, -1), (i, a1, 1), (j, a2, 1)], kind="back")
    matched = np.zeros(L, dtype=bool)
    zmax = 0.0
    n1 = int(changed.sum())
    for (d, df, dw, kind), cs in pats.items():
        m = (dn == np.array(d)).all(1) & changed
        if kind == "turn":
            m &= (dh != 0) & (pos == 0)
        elif kind == "fwd":
            m &= pos == 3          # heading 0: x + 1
        elif kind == "back":
            m &= pos == 6          # x - 1 on a 3-torus
        else:
            m &= (dh == 0) & (pos == 0) & (dfo == df) & (dwo == dw)
        if kind == "plain":
            pass
        else:
            m &= (dfo == 0) & (dwo == 0)
        obs = int(m.sum())
        exp = n1 * r1[cs].sum() / tot
        matched |= m
        if exp > 0 or obs > 0:
            zmax = max(zmax, abs(obs - exp) / np.sqrt(max(exp, 1.0)))
    unmatched = int((changed & ~matched).sum())
    # lanes with two events in the leap match no single pattern: expected fraction tot * dt / 2
    eff_ok = zmax < 5.0 and unmatched <= 2 * n1 * 0.005 + 10
    return rate_ok and eff_ok, dict(rate_max_relative_error=worst, single_event_lanes=n1, effect_max_z=zmax,
                                    unmatched_lanes=unmatched)


CHECKS = {k[len("check_"):]: v for k, v in list(globals().items()) if k.startswith("check_")}


# ---------- life layer (mandatory) ----------

LIFE_LEAN = ("exposed", "metabolizes")
LIFE_LINEAGE = {
    "sense": ["CGB.Medium.Lives.exposed", "CGB.tableCRN.exposed_of_rule"],
    "metabolism": ["CGB.Medium.Lives.metabolizes", "CGB.tableCRN.metabolizes_of_rule"],
    "export": ["CGB.Generation.export_forced"],
    "selective_export": ["CGB.Generation.retention_needs_selectivity"],
    "memory": ["CGB.Generation.memory_separates", "CGB.Medium.hold_vanishes"],
    "self_maintenance": ["CGB.Medium.not_selfMaintains_of_unexposed"],
}


def _table_arrays(t):
    """Arrays for the exact simulator of multi-state pair tables (`cgb_table3`)."""
    from cgb_table_medium import unit_pages
    P = len(t["pages"])
    pages = unit_pages(t)
    S = max([int(v) for v in t.get("states", {}).values()] or [2])
    counts = np.array([pages.count(p) for p in range(P)], dtype=np.int64)
    phi = np.zeros((P, S))
    for p in range(P):
        v = t["phi"][str(p)]
        phi[p, :len(v)] = v
    bnd = np.zeros(P, dtype=np.bool_)
    bnd[list(t["boundary_pages"])] = True
    R = np.array([[r["i"], r["j"], -1, r["a"][0], r["a"][1], 0, r["b"][0], r["b"][1], 0] for r in t["rules"]],
                 dtype=np.int64).reshape(-1, 9)
    kap = np.array([r["kappa"] for r in t["rules"]], dtype=np.float64)
    return counts, phi, bnd, R, kap, S


def life_export(t):
    """G16 and G17 on the table: content-lowering boundary events exist, and their calm
    propensities (per source kind: pages and states of the two units) are not all equal."""
    import math
    from cgb_table_medium import rule_dirs, dE
    bnd = set(t["boundary_pages"])
    calm = {p: 0.0 for p in range(len(t["pages"]))}
    props = {}
    for k, back, r, src, dst in rule_dirs(t):
        if not ({r["i"], r["j"]} & bnd) or sum(dst) >= sum(src):
            continue
        key = (r["i"], src[0], r["j"], src[1])
        props[key] = props.get(key, 0.0) + r["kappa"] * math.exp(-dE(t, r["i"], r["j"], src, dst, calm) / 2)
    vals = sorted(props.values())
    ratio = vals[-1] / vals[0] if len(vals) > 1 and vals[0] > 0 else 1.0
    return dict(export=bool(vals), selective=len(vals) > 1 and ratio > 1 + 1e-9, kinds=len(vals),
                max_min_ratio=ratio)


def life_memory(t, probe, mu_pulse, reps=600, seed=11, lags=(1, 2, 4, 8, 16, 32), rest=None):
    """Finite-horizon Remembers: a +-mu pulse on the probe page for one tick, then rest (the
    organism's resting reservoir potentials `rest`, default all zero). The sign is decoded from the
    per-page per-state counts `lag` rest ticks later (mean-difference projection fitted on half
    the replicates, tested on the other half)."""
    from cgb_table3 import _run
    counts, phi, bnd, R, kap, S = _table_arrays(t)
    P = counts.shape[0]
    base = np.zeros(P)
    for p, v in (rest or {}).items():
        base[int(p)] = v
    np.random.seed(seed)
    signs = np.random.default_rng(seed).choice([-1.0, 1.0], size=reps)
    feats = np.zeros((len(lags), reps, P * S))
    flux = np.zeros(P)
    for r in range(reps):
        n = np.zeros((P, S), dtype=np.int64)
        n[:, 0] = counts
        mu = base.copy()
        _run(n, phi, bnd, mu, R, kap, 20.0, flux)
        mu[probe] = base[probe] + signs[r] * mu_pulse
        _run(n, phi, bnd, mu, R, kap, 1.0, flux)
        mu[:] = base
        last = 0
        for li, lag in enumerate(lags):
            _run(n, phi, bnd, mu, R, kap, float(lag - last), flux)
            last = lag
            feats[li, r] = n.reshape(-1)
    half = reps // 2
    curve = {}
    for li, lag in enumerate(lags):
        X, y = feats[li], signs
        w = X[:half][y[:half] > 0].mean(0) - X[:half][y[:half] < 0].mean(0)
        thr = np.median(X[:half] @ w)
        acc = float(np.mean(np.where(X[half:] @ w > thr, 1.0, -1.0) == y[half:]))
        curve[lag] = dict(accuracy=acc, z=(acc - 0.5) / (0.25 / (reps - half)) ** 0.5)
    horizon = max([lag for lag in lags if curve[lag]["z"] > 3.0], default=0)
    return dict(curve=curve, horizon=horizon, passed=curve[lags[0]]["z"] > 3.0)


def life_self_maintenance(record, cut_arm):
    ho = json.loads((ROOT / record).read_text(encoding="utf-8"))["held_out"]
    org = [x["survival"] for x in ho["organism"]]
    cut = [x["survival"] for x in ho[cut_arm]]
    return dict(organism_mean=float(np.mean(org)), cut_mean=float(np.mean(cut)),
                organism_median=float(np.median(org)), cut_median=float(np.median(cut)),
                passed=bool(np.mean(org) > np.mean(cut) and np.median(org) >= np.median(cut)))


def life_layer(man, decls):
    """Returns (rows, failures). A manifest without a `life` section fails: it is mandatory."""
    spec = man.get("life")
    if not spec:
        return [], ["life layer: manifest has no `life` section (mandatory)"]
    rows, failures = [], []
    module = man.get("lean_medium", "").rsplit(".", 1)[0]
    for nm in LIFE_LEAN:
        d = decls.get(f"{module}.{nm}")
        rows.append(dict(item=f"lean:{nm}", passed=d is not None and set(d["axioms"]) <= STANDARD))
    for item, thms in LIFE_LINEAGE.items():
        missing = [x for x in thms if x not in decls]
        if missing:
            failures.append(f"life: lineage of {item} missing {missing}")
    from cgb_table_medium import load
    t = load(ROOT / "information_boltzmann" / "organisms" / f"{spec['table']}.json")
    ex = life_export(t)
    rows.append(dict(item="export", passed=ex["export"], kinds=ex["kinds"]))
    rows.append(dict(item="selective_export", passed=ex["selective"], max_min_ratio=ex["max_min_ratio"]))
    mem = life_memory(t, spec["probe_page"], spec["pulse_mu"], rest=spec.get("rest_mu"))
    rows.append(dict(item="memory", passed=mem["passed"], horizon=mem["horizon"], curve=mem["curve"]))
    rows.append(dict(item="self_maintenance", **life_self_maintenance(spec["record"], spec["cut_arm"])))
    failures += [f"life: {r['item']} failed" for r in rows if not r["passed"]]
    return rows, failures


# ---------- gate ----------

def gate(name):
    man = json.loads((ARCH / f"{name}.json").read_text(encoding="utf-8"))
    decls, fresh, trusted = load_inventory()
    lineage, execution, failures = [], [], []
    if not fresh:
        failures.append("Lean inventory is stale: rebuild and run lean/CGBAxioms/scripts/audit.py")
    if not trusted:
        failures.append("Lean audit trust/coverage did not pass")
    for mech in man["mechanisms"]:
        row = dict(id=mech["id"], kind=mech["kind"], theorems={})
        for t in mech.get("theorems", []):
            d = decls.get(t)
            row["theorems"][t] = ("missing" if d is None else
                                  "nonstandard axioms" if not set(d["axioms"]) <= STANDARD else "ok")
        licensed = bool(row["theorems"]) and all(v == "ok" for v in row["theorems"].values())
        if mech["kind"] == "constant":
            row["status"] = "constant (allowed)"
        elif mech["kind"] == "selected":
            ev = mech.get("evidence")
            row["status"] = "selected (allowed)" if ev and (ROOT / ev).exists() else "UNLICENSED"
            if row["status"] == "UNLICENSED":
                failures.append(f"{mech['id']} (selected): selection record missing")
        elif licensed:
            row["status"] = "licensed"
        else:
            row["status"] = "UNLICENSED"
            failures.append(f"{mech['id']} ({mech['kind']}): no valid Lean theorem")
        lineage.append(row)
        if not licensed:
            continue
        if not mech.get("checks"):
            failures.append(f"{mech['id']}: licensed but no executable check on the implementation")
        for c in mech.get("checks", []):
            fn, _, arg = c.partition(":")
            try:
                if fn not in CHECKS:
                    ok, info = False, dict(error="unknown check")
                else:
                    ok, info = CHECKS[fn](arg) if arg else CHECKS[fn]()
            except Exception as exc:  # a crashing check is a failing check
                ok, info = False, dict(error=repr(exc))
            execution.append(dict(mechanism=mech["id"], check=c, passed=bool(ok), **info))
            if not ok:
                failures.append(f"{mech['id']}: check {c} failed")
    med = man.get("lean_medium")
    if not med:
        failures.append("no Lean Medium instance with an Axioms proof")
    elif med not in decls:
        failures.append(f"Lean Medium instance {med} not in inventory")
    if man.get("role") == "world":   # a world is not alive: it must only be an axiom model
        life, lf = [], []
    else:
        life, lf = life_layer(man, decls)
    failures += lf
    return dict(architecture=name, implementation=man.get("implementation"), inventory_fresh=fresh,
                lineage=lineage, execution=execution, lean_medium=med, life=life,
                admitted=not failures, failures=failures)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("name")
    ap.add_argument("--json")
    ap.add_argument("--require-admitted", action="store_true")
    a = ap.parse_args()
    r = gate(a.name)
    if a.json:
        Path(a.json).write_text(json.dumps(r, indent=1), encoding="utf-8")
    print(f"{r['architecture']}: {'ADMITTED' if r['admitted'] else 'NOT ADMITTED'}")
    for row in r["lineage"]:
        print(f"  [{row['status']}] {row['id']}")
    for e in r["execution"]:
        print(f"  check {e['check']}: {'pass' if e['passed'] else 'FAIL'}")
    for row in r.get("life", []):
        extra = {k: v for k, v in row.items() if k not in ("item", "passed", "curve")}
        print(f"  life {row['item']}: {'pass' if row['passed'] else 'FAIL'} {extra if extra else ''}")
    for f in r["failures"]:
        print("  - " + f)
    return 1 if (a.require_admitted and not r["admitted"]) else 0


if __name__ == "__main__":
    raise SystemExit(main())
